class Solution:
    def maxTaskAssign(self, tasks, workers, pills, strength):
        from collections import deque
        sorted_tasks = sorted(tasks)
        sorted_workers = sorted(workers)

        def can(k):
            queue = deque()
            task_index = 0
            pills_left = pills
            selected_workers = sorted_workers[-k:] if k else []
            for worker in selected_workers:
                while task_index < k and sorted_tasks[task_index] <= worker + strength:
                    queue.append(sorted_tasks[task_index])
                    task_index += 1
                if not queue:
                    return False
                if queue[0] <= worker:
                    queue.popleft()
                else:
                    if pills_left == 0:
                        return False
                    queue.pop()
                    pills_left -= 1
            return True

        low, high = 0, min(len(tasks), len(workers))
        while low < high:
            mid = (low + high + 1) // 2
            if can(mid):
                low = mid
            else:
                high = mid - 1
        return low

